from fractions import Fraction
from typing import Any


def _number(value: Any) -> Fraction:
    """Convert a supported numeric value to an exact rational number."""
    if value is None:
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Fraction(0)
        return Fraction(value)

    if isinstance(value, float):
        # Convert through the decimal representation rather than preserving
        # the float's binary approximation.
        return Fraction(str(value))

    return Fraction(value)


def _account_key(value: Any) -> tuple[str, Any]:
    """Normalize account identifiers for matching."""
    try:
        return ("number", _number(value))
    except (TypeError, ValueError, ZeroDivisionError):
        return ("text", "" if value is None else str(value))


def _sort_key(value: Any) -> tuple[int, Any]:
    """Provide deterministic primary-key ordering."""
    normalized_type, normalized_value = _account_key(value)
    if normalized_type == "number":
        return (0, normalized_value)
    return (1, normalized_value)


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[tuple[str, Any], Fraction] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        key = _account_key(order.get("ACCT_ID"))
        exposure_by_account[key] = (
            exposure_by_account.get(key, Fraction(0))
            + _number(order.get("TOT_AMT"))
        )

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(
        key=lambda index: _sort_key(new_accounts[index].get("ACCT_ID"))
    )

    for index in eligible_indices:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(
            _account_key(account_id),
            Fraction(0),
        )
        credit_limit = _number(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure <= credit_limit * Fraction(8, 10)
            and account.get("CRED_HOLD") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
